using System;
using System.Collections.Generic;
using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;

namespace Media.DBContext.Models;

/// <summary>
/// Represents a filter rule which determines the records synchronized with a partner.
/// </summary>
[Table("federation_rules")]
public class FederationRule
{
  /// <summary>
  /// Primary key. Autogenerated.
  /// </summary>
  [Key]
  public Guid RuleId { get; set; }

  /// <summary>
  /// The partners the rule is restricted to. Empty applies to all partners.
  /// </summary>
  public ICollection<FederationPeer> Peers { get; set; } = [];

  /// <summary>
  /// The direction the rule is applied to.
  /// </summary>
  public int Direction { get; set; }

  /// <summary>
  /// Artists the rule matches. Empty matches all artists.
  /// </summary>
  public ICollection<Artist> Artists { get; set; } = [];

  /// <summary>
  /// Albums the rule matches. Empty matches all albums.
  /// </summary>
  public ICollection<Album> Albums { get; set; } = [];

  /// <summary>
  /// Genres the rule matches. Empty matches all genres.
  /// </summary>
  public ICollection<Genre> Genres { get; set; } = [];

  /// <summary>
  /// Date when the rule was created.
  /// </summary>
  public DateTime CreatedAt { get; set; }

  /// <summary>
  /// The groups incoming records matching the rule are assigned to.
  /// </summary>
  public ICollection<Group> Groups { get; set; } = [];
}
